try { $BasePath="C:\Users\Public"; $RandomFolderName="SelectiveExclusionSim_"+([guid]::NewGuid().ToString()); $TargetFolder=Join-Path $BasePath $RandomFolderName; if(-not(Test-Path $TargetFolder)){ New-Item -Path $TargetFolder -ItemType Directory | Out-Null }; $normalExtensions=@("txt","docx","jpg","ps1","png"); $excludedExtensions=@("exe","dll"); $filesPerExtension=60; $repeatContentFactor=120; Write-Output ">> Normal files <<"; foreach($ext in $normalExtensions){ 1..$filesPerExtension | ForEach-Object { $filePath=Join-Path $TargetFolder ("file_{0}_{1}.{2}" -f $ext,$_,$ext); $content=("Dummy content for $ext file $_. " * $repeatContentFactor).Trim(); Set-Content -Path $filePath -Value $content -Encoding UTF8; Write-Output "[] Created: $filePath" } }; Write-Output ">> Excluded files <<"; foreach($ext in $excludedExtensions){ 1..$filesPerExtension | ForEach-Object { $filePath=Join-Path $TargetFolder ("excluded_{0}_{1}.{2}" -f $ext,$_,$ext); [Byte[]]$data=0..255; [System.IO.File]::WriteAllBytes($filePath,$data); Write-Output "[] Created: $filePath" } }; $rsa=[System.Security.Cryptography.RSACryptoServiceProvider]::new(2048); $publicKey=$rsa.ToXmlString($false); $privateKey=$rsa.ToXmlString($true); Set-Content -Path (Join-Path $TargetFolder "publicKey.xml") -Value $publicKey; Set-Content -Path (Join-Path $TargetFolder "privateKey.xml") -Value $privateKey; Get-ChildItem -Path $TargetFolder -File | Where-Object { $_.Extension -notin @(".exe",".dll",".xml") } | ForEach-Object { $plainBytes=[System.IO.File]::ReadAllBytes($_.FullName); if($plainBytes.Length -gt 214){ $plainBytes=$plainBytes[0..213] }; $cipherBytes=$rsa.Encrypt($plainBytes,$true); $encPath="$($_.FullName).enc"; [System.IO.File]::WriteAllBytes($encPath,$cipherBytes); Remove-Item $_.FullName -Force }; Write-Host "[!] Encryption completed"; Get-ChildItem "$BasePath\$RandomFolderName" } catch { Write-Error "An error occurred: $_"; exit 1 }; Remove-Item "$BasePath\$RandomFolderName" -Recurse -Force;